const CLIENT_BUILD_ID='__LINKLENSE_BUILD_ID__';
const auditViewports=a=>a.viewports||[...new Set(a.pageResults.map(p=>p.viewport))];
const viewportLabel=a=>auditViewports(a).map(v=>v==='Desktop'?'Desktop Web App':'Mobile Web App').join(' & ');
const $=s=>document.querySelector(s);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',link:'M10 13a5 5 0 0 0 7 .5l3-3a5 5 0 0 0-7-7l-2 2 M14 11a5 5 0 0 0-7-.5l-3 3a5 5 0 0 0 7 7l2-2',clock:'M12 8v5l3 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',plus:'M12 5v14 M5 12h14',arrow:'M5 12h14 M14 7l5 5-5 5',download:'M12 3v12 M7 10l5 5 5-5 M4 16v5h16v-5',search:'M21 21l-5-5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',globe:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0 M2 12h20 M12 2c6 5 6 15 0 20-6-5-6-15 0-20',check:'M5 12l4 4L19 6',alert:'M12 8v5 M12 17h.01 M12 3L2 21h20z',info:'M12 11v6 M12 7h.01 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',close:'M6 6l12 12 M6 18L18 6',lock:'M5 10h14v11H5z M8 10V6a4 4 0 0 1 8 0v4',file:'M5 2h9l5 5v15H5z M14 2v6h5 M8 13h8 M8 17h6',layers:'M12 2L2 7l10 5 10-5z M2 12l10 5 10-5 M2 17l10 5 10-5',monitor:'M2 3h20v14H2z M12 17v5 M7 22h10',chevron:'M9 5l7 7-7 7'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.link}"/></svg>`;
const labels={pass:'Passed',broken:'Broken link',alt:'Link name issue',unverified:'No destination verdict',review:'Contextual review',performance:'Redirects'};
const colors={pass:'#43856d',broken:'#c4626c',alt:'#d3a04f',unverified:'#6a7584',review:'#8b7bcb',performance:'#91a0b6'};
// Verification groups are derived from recorded evidence, including saved reports.
const outcomeLabels={working:'Verified working',broken:'Confirmed broken',incomplete:'Access & response details',manual:'Interactive controls & app actions'};
function verificationResult(a){
 const issues=a.issues||[],has=k=>issues.some(i=>i.severity===k);
 const result=(group,code,label,detail,next)=>({group,code,label,detail,next});
 if(has('broken'))return result('broken','confirmed-broken','Confirmed broken',issues.filter(i=>i.severity==='broken').map(i=>i.message).join(' '),'Inspect the failure evidence and correct or retry the destination.');
 if(a.loaded===true&&!has('unverified'))return result('working','verified-working','Verified working','The destination or fragment was verified in the audited browser session.','Review any separate naming or usability findings.');
 const reason=a.reason||issues.find(i=>i.code==='destination-unverified')?.message||'';
 if(/sign.in or verification|requires sign.in/i.test(reason))return result('incomplete','sign-in-required','Sign-in required',reason,'Reconnect the intended signed-in session and run the audit again.');
 if(a.httpStatus===429||/rate limit/i.test(reason)&&!a.httpStatus)return result('incomplete','rate-limited','Rate limited',reason||'HTTP 429 prevented verification.','Wait for the site’s rate limit to clear, then run a smaller audit.');
 if([401,403].includes(a.httpStatus)||/access restrictions|access.*prevent verification/i.test(reason))return result('incomplete','access-restricted','Access restricted',reason||`HTTP ${a.httpStatus} prevented verification.`,'Check account permissions or site restrictions, then retry in the intended session.');
 if(/storage could not|Source application was not available/i.test(reason))return result('incomplete','session-unavailable','Session unavailable',reason,'Reconnect your application session before running another audit.');
 if(/limit reached/i.test(reason))return result('incomplete','scan-limit','Scan limit reached',reason,'Use selected-page audits to check the remaining destinations.');
 if(/failed or timed out/i.test(reason))return result('incomplete',/timeout|timed out/i.test(reason.replace('Browser destination verification failed or timed out: ',''))?'timed-out':'browser-check-failed',/timeout|timed out/i.test(reason.replace('Browser destination verification failed or timed out: ',''))?'Check timed out':'Browser check failed',reason,'Open the destination in the intended session and retry the audit when it is available.');
 if(/embedded credentials/i.test(reason))return result('manual','embedded-credentials','Credential URL skipped',reason,'Use a URL without embedded credentials and connect through the sign-in workflow.');
 if(/Download or potential action/i.test(reason)||a.download)return result('manual','action-skipped',a.download?'Download not activated':'Action not activated',reason||'The download was not activated.','Check this action separately in an appropriate test session.');
 if(/^[a-z][a-z0-9+.-]*: destination requires manual/i.test(reason)||/^(mailto:|tel:|sms:|javascript:)/i.test(a.source||''))return result('manual','external-action',/^javascript:/i.test(a.source||'')?'Script action':'External-app action',reason||'This control runs script rather than exposing a web destination.','Verify the action with its intended application or workflow.');
 if(issues.some(i=>i.code==='scripted-destination')||a.verification==='scripted-control'||/did not expose a navigation destination/i.test(reason))return result('manual','scripted-control','Scripted control',reason||'No web destination could be established for this control. Its action has not been verified.','Test the control’s expected behavior in the application.');
 if(/fragment target was not found/i.test(reason))return result('incomplete','fragment-inconclusive','Fragment needs review',reason,'Check whether the target appears after the required page interaction.');
 if(/rendered content despite HTTP/i.test(reason))return result('incomplete','response-conflict','Response needs review',reason,'Compare the rendered content with the HTTP response in the intended session.');
 return result('incomplete','inconclusive','No reliable verdict',reason||'The recorded evidence does not establish a working or broken destination.','Inspect the evidence and repeat the check in the intended session.');
}
const resultFilterEntries=()=>[...Object.entries(outcomeLabels).map(([k,l])=>['outcome:'+k,l]),...new Map(audit.assets.map(a=>{const v=verificationResult(a);return ['reason:'+v.code,v.label]})).entries()];
function verificationHTML(a){const v=verificationResult(a);return `<div class="verification-evidence"><span class="badge ${v.group==='working'?'pass':v.group==='broken'?'broken':'unverified'}">${esc(v.label)}</span>${['incomplete','manual'].includes(v.group)?`<p class="verification-reason">${esc(v.detail)}</p><p class="verification-next"><strong>Next:</strong> ${esc(v.next)}</p>`:''}</div>`}
function separationHTML(){
 const d=destinationSummary(audit.assets),incompleteURLs=new Set(audit.assets.filter(a=>verificationResult(a).group==='incomplete').map(a=>a.source||a.page+'|'+a.selector)).size;
 const card=k=>`<button data-filter="outcome:${k}" class="outcome-card ${k}"><span>${outcomeLabels[k]}</span><strong>${k==='incomplete'?incompleteURLs:d[k]}</strong><small>${{working:'Verified observations, including each occurrence and viewport',broken:'Failure observations, including each occurrence and viewport',incomplete:`Destination URLs · ${d.incomplete} recorded checks across pages and viewports.`,manual:'Controls, downloads and external-app actions'}[k]}</small></button>`;
 const reasons=group=>{const counts=new Map();for(const a of audit.assets){const v=verificationResult(a);if(v.group===group){const prev=counts.get(v.code);counts.set(v.code,{...v,count:(prev?.count||0)+1})}}return counts.size?`<div class="reason-group"><h3>${group==='incomplete'?'Access and response reasons':'Control and action types'}</h3><div class="reason-buttons">${[...counts.values()].map(v=>`<button data-filter="reason:${v.code}">${esc(v.label)} <strong>${v.count}</strong></button>`).join('')}</div></div>`:''};
 return `<section class="result-separation" aria-label="Verification results"><div class="section-heading"><div><h2>Link results</h2><p class="small">Working and broken counts include every occurrence. Access & response details group repeated checks for the same URL.</p></div></div><div class="outcome-grid">${['working','broken','incomplete'].map(card).join('')}</div>${reasons('incomplete')}<p class="small">${d.incomplete?'Access and response conditions are listed with their recorded evidence.':'All destination checks returned a conclusive result.'} Every observation remains available in All links.</p><details class="separate-actions"><summary>Interactive controls & app actions <span>${d.manual} action observations</span></summary><p class="small">These controls were not established as web destinations, or were intentionally not activated. This section covers scripted controls, downloads and links that open other applications. Destination success uses verified web outcomes; action behavior is a separate test scope.</p>${card('manual')}${reasons('manual')}</details></section>`;
}
let saved=[];try{saved=JSON.parse(localStorage.getItem('linklense-audits-v1')||'[]').filter(a=>a.sampleData===false&&Array.isArray(a.assets));}catch{}
let audit=saved[0]||null,tab='overview',view='audit',filter='confirmed',query='',pageFilter='',typeFilter='',viewportFilter='',pageNum=1,setup={},activeJob=null,storageWarning='';
const api=async(path,data,method=data?'POST':'GET')=>{let res=await fetch('/api/'+path,{method,headers:{'Content-Type':'application/json','X-LinkLense':'1','X-LinkLense-Build':CLIENT_BUILD_ID},...(data?{body:JSON.stringify(data)}:{})});let value=await res.json();if(!res.ok)throw Error(value.error||'Request failed.');return value};
const pageLabel=url=>{try{let u=new URL(url);return u.pathname+u.search+u.hash}catch{return url}};
const totals=()=>Object.fromEntries(Object.keys(labels).map(k=>[k,audit.assets.filter(a=>a.status===k).length]));
const hasStatus=(a,k)=>k.startsWith('outcome:')?verificationResult(a).group===k.slice(8):k.startsWith('reason:')?verificationResult(a).code===k.slice(7):k==='all'||k==='issues'&&a.issues.length>0||k==='confirmed'&&a.issues.some(i=>['broken','alt'].includes(i.severity))||k==='pass'&&!a.issues.length||a.issues.some(x=>x.severity===k);
function toast(text){$('#toast').textContent=text;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',4500)}
function render(){
 const home=view==='home'||(view==='audit'&&!audit);
 $('#app').innerHTML=`<header class="app-header"><div class="header-inner"><a href="/" class="brand" data-action="home" aria-label="LinkLense home"><img src="brand/linklens-logo-v2.png" alt="LinkLens" width="2087" height="753"></a><nav class="nav" aria-label="Main navigation"><button class="${home?'active':''}" data-action="home" ${home?'aria-current="page"':''}>Home</button><button aria-label="Audit overview" class="${!home&&view==='audit'?'active':''}" data-action="audit" ${!home&&view==='audit'?'aria-current="page"':''}>${icon('grid')}<span>Audit overview</span></button><button aria-label="Scan history" class="${view==='history'?'active':''}" data-action="history" ${view==='history'?'aria-current="page"':''}>${icon('clock')}<span>Scan history</span></button></nav><div class="header-tools"><label class="theme-control"><span class="sr-only">Appearance</span><select id="theme-select" aria-label="Appearance">${[['system','System'],['light','Light'],['dark','Dark']].map(([v,l])=>`<option value="${v}" ${window.lensTheme.preference===v?'selected':''}>${l}</option>`).join('')}</select></label><button class="primary btn-icon header-new" data-action="new">${icon('plus')}<span>New audit</span></button></div></div></header><div class="shell"><div class="workspace-context" role="region" aria-label="Workspace context"><span class="eyebrow">LENS / LINK INTEGRITY</span><span class="local-note">${icon('lock')} Local workspace <span class="build-label">· ${CLIENT_BUILD_ID.slice(0,8)}</span></span></div><main class="main ${home?'home-main':''}" id="main" tabindex="-1">${view==='history'?historyHTML():home?emptyHTML():auditHTML()}</main><footer class="app-footer"><span><strong>LENS</strong> A clearer view of your web.</span><span>LinkLens · Reports saved in this browser</span></footer></div>`;
 bindMain();
}
function emptyHTML(){return `<section class="hero"><div class="hero-copy"><div class="eyebrow hero-eyebrow"><span class="tiny-mark" aria-hidden="true"></span> THE LINK INTEGRITY WORKSPACE</div><h1>Every link.<br>A clearer picture.</h1><p class="hero-intro">Find broken destinations. Understand signed-in journeys. See the evidence behind every result.</p><form id="start-audit-form" class="url-launch"><label for="start-url">Where should we look?</label><div class="url-entry"><span aria-hidden="true">${icon('globe')}</span><input id="start-url" type="url" placeholder="https://your-website.com" autocomplete="url" spellcheck="false" aria-describedby="url-hint"><button type="submit" class="primary btn-icon" aria-label="Start your first audit">Start audit ${icon('arrow')}</button></div><p id="url-hint" class="small">Choose pages, sign-in access and viewports in the next step.</p></form><div class="start-features"><span>${icon('monitor')} Desktop & mobile</span><span>${icon('lock')} Checks run headlessly</span></div></div><aside class="journey" aria-label="How a link audit works"><div class="journey-heading"><span class="eyebrow">FROM URL TO UNDERSTANDING</span><span class="journey-cross" aria-hidden="true">+</span></div><div class="journey-step"><span class="journey-node">${icon('globe')}</span><div><span class="step-kicker">01 / SCOPE</span><h2>Your website, connected.</h2><p>One page, chosen pages or the discovered website. Public or signed in.</p></div></div><div class="journey-step"><span class="journey-node">${icon('link')}</span><div><span class="step-kicker">02 / INSPECT</span><h2>Follow the evidence.</h2><p>Check destinations, link names and supported navigation in a real browser.</p></div></div><div class="journey-step"><span class="journey-node final-node">${icon('search')}</span><div><span class="step-kicker">03 / UNDERSTAND</span><h2>Know what needs attention.</h2><p>Confirmed failures and other observations stay separate.</p></div></div><div class="journey-foot">${icon('file')} Every finding has a story. Inspect the details.</div></aside></section><section class="home-workspace"><div class="section-heading"><div><span class="eyebrow">YOUR WORKSPACE</span><h2>${saved.length?'Pick up where you left off.':'Built for a closer look.'}</h2></div>${saved.length?`<button class="text-btn btn-icon" data-action="history">All scan history ${icon('arrow')}</button>`:''}</div>${saved.length?`<div class="recent-audits">${saved.slice(0,3).map((a,i)=>`<button class="recent-audit" data-history="${i}"><span class="recent-icon">${icon('globe')}</span><span class="recent-site"><strong>${esc(new URL(a.url).hostname)}</strong><small>${esc(a.scope)} · ${a.pages.length} pages · ${esc(auditViewports(a).join(' + '))}</small></span><span class="recent-date">${new Date(a.date).toLocaleDateString()}</span>${icon('arrow')}</button>`).join('')}</div>`:`<div class="principles"><article><span class="principle-number">01</span><div><h3>Coverage you can understand.</h3><p>See which pages and viewports were checked, along with anything the scanner could not verify.</p></div></article><article><span class="principle-number">02</span><div><h3>Evidence you can take with you.</h3><p>Inspect individual occurrences, filter the report and export HTML, PDF, CSV or JSON.</p></div></article></div>`}</section>`}
function failedPagesHTML(){const failures=audit.pageResults.filter(p=>p.status==='broken');return failures.length?`<div class="coverage failed-pages" role="alert">${icon('alert')}<span><strong>Audited URL failed.</strong> ${failures.map(p=>`${esc(p.url)} · ${esc(p.viewport)} · HTTP ${p.httpStatus}`).join('<br>')}<br>These failed page checks are included in Broken links as “Audited URL” findings. Links inside their error pages were not scanned.</span></div>`:''}
function auditHTML(){const t=totals(),broken=audit.assets.filter(a=>hasStatus(a,'broken')).length,alt=audit.assets.filter(a=>hasStatus(a,'alt')).length,review=audit.assets.filter(a=>hasStatus(a,'review')).length;return `<div class="heading"><div><span class="eyebrow">AUDIT OVERVIEW</span><h1>The details. In focus.</h1><p>What works, what needs attention, and the evidence to act on.</p></div><div class="actions"><button class="btn-icon" data-action="export">${icon('download')} Export report</button><button class="primary btn-icon" data-action="new">${icon('plus')} New audit</button></div></div>${audit.buildId!==CLIENT_BUILD_ID?`<div class="coverage-note" role="status">Saved scan from an earlier or unidentified build. These findings reflect that scan; the current layout separates its recorded evidence. Run a new audit for current results.</div>`:''}${storageWarning?`<div class="coverage-note" role="alert">${icon('alert')}<span><strong>Report not saved.</strong> ${esc(storageWarning)} Export it before closing this tab.</span></div>`:''}<section class="site-strip" aria-label="Audit scope"><span class="site-icon">${icon('globe')}</span><div class="site-info"><strong>${esc(new URL(audit.url).hostname)}</strong><div class="small">${esc(audit.scope)} · ${audit.pages.length} pages · ${viewportLabel(audit)} · ${audit.access==='public'?'Public access':'Signed-in session'} · ${new Date(audit.date).toLocaleString()}</div></div><span class="badge ${audit.pageResults.some(p=>p.status==='broken')?'broken':audit.unverified||destinationSummary(audit.assets).incomplete?'unverified':'pass'}">${icon(audit.pageResults.some(p=>p.status==='broken')?'alert':destinationSummary(audit.assets).incomplete?'info':'check')} ${audit.pageResults.some(p=>p.status==='broken')?'Audited URL failed':audit.pageResults.every(p=>p.status==='unverified')?(audit.coverage.gaps.some(g=>g.reason==='Sign-in required')?'Sign-in required':'No pages verified'):destinationSummary(audit.assets).incomplete?'Audit complete':'Audit finished'}</span></section>${failedPagesHTML()}<div class="coverage-note">${icon('info')}<span><strong>Coverage is part of the result.</strong> ${audit.assets.length} link and control observations across ${audit.pages.length} selected pages and ${auditViewports(audit).length} viewport(s). ${audit.coverage.gaps.length} coverage notes. ${esc(audit.coverage.note)}</span></div><section class="metrics" aria-label="Audit summary">${metric('Recorded observations',audit.assets.length,`${audit.coverage.uniqueResources} unique destinations · each viewport retained`,'link')}${metric('Broken links',broken,'Failed link occurrences and audited URLs','alert','var(--red)')}${metric('Link name issues',alt,'Occurrences with accessible name issues','layers','var(--amber)')}${metric('Contextual findings',review,'Context and destination intent','search','var(--accent)')}</section><div class="tabs" role="tablist" aria-label="Report sections">${[['overview','Overview'],['findings','All links'],['coverage','Page coverage']].map(([id,l])=>`<button role="tab" id="tab-${id}" aria-controls="report-content" aria-selected="${tab===id}" tabindex="${tab===id?'0':'-1'}" class="${tab===id?'active':''}" data-tab="${id}">${l}${id==='findings'?`<span class="count">${audit.assets.length}</span>`:''}</button>`).join('')}</div><div id="report-content" role="tabpanel" aria-labelledby="tab-${tab}">${tab==='overview'?separationHTML()+chartsHTML(t)+findingsHTML():tab==='findings'?findingsHTML():coverageHTML()}</div><p class="footer-note">LinkLens · ${Math.round(audit.durationMs/1000)} seconds · Automated checks and contextual review are reported separately.</p>`}
function metric(label,num,sub,ic,color='var(--ink)'){return `<div class="metric"><div class="metric-top">${label}${icon(ic)}</div><strong style="color:${color}">${num}</strong><span class="small">${sub}</span></div>`}
function destinationSummary(assets){
 const counts={working:0,broken:0,incomplete:0,manual:0};for(const a of assets)counts[verificationResult(a).group]++;
 const checked=counts.working+counts.broken;return{...counts,checked,unverified:counts.incomplete+counts.manual,rate:checked?Math.round(counts.working/checked*100):null};
}
function destinationSummaryHTML(){const d=destinationSummary(audit.assets);return `<p class="destination-summary"><strong>${d.rate===null?'No verified destination outcomes':d.rate+'% destination success'}</strong> · ${d.working} working / ${d.checked} verified observations. ${d.incomplete} access or response conditions; ${d.manual} interactive control and app-action observations. Both groups are excluded from the success rate. Verification coverage: ${d.checked} / ${audit.assets.length} observations. ${d.unverified?'This success rate describes verified results only; the audit has observations without a destination verdict.':'All recorded observations have a destination verdict.'} Link name issues and review notes are reported separately.${audit.assets.some(a=>a.auditedURL)?' Failed audited URLs are included as destination failures; they are not link elements.':''}</p>`;}
function chartsHTML(t){const d=destinationSummary(audit.assets),split=d.checked?d.working/d.checked*100:0;let affected=audit.pages.map(p=>({p,broken:audit.assets.filter(a=>a.page===p&&hasStatus(a,'broken')).length,names:audit.assets.filter(a=>a.page===p&&hasStatus(a,'alt')).length,n:audit.assets.filter(a=>a.page===p&&a.issues.some(i=>['broken','alt'].includes(i.severity))).length})).filter(x=>x.n).sort((a,b)=>b.n-a.n).slice(0,5);return `<div class="charts"><section class="panel"><div class="panel-head"><div><h2>Destination checks</h2><p>Success rate among verified outcomes</p></div>${icon('link')}</div><div class="health-content"><div class="donut" style="background:${d.checked?`conic-gradient(${colors.pass} 0% ${split}%,${colors.broken} ${split}% 100%)`:'#ececf2'}" role="img" aria-label="${d.working} working of ${d.checked} verified destination observations; ${d.incomplete} limited checks and ${d.manual} action observations excluded"><div class="donut-hole"><strong>${d.rate??'—'}${d.checked?'<span style="font-size:17px">%</span>':''}</strong><span class="small">destination success</span></div></div><div class="legend">${Object.entries(outcomeLabels).filter(([k])=>k!=='manual').map(([k,l])=>`<button data-filter="outcome:${k}"><span class="dot" style="--color:${colors[{working:'pass',broken:'broken',incomplete:'unverified',manual:'performance'}[k]]}"></span>${l}<strong>${d[k]}</strong></button>`).join('')}</div></div><div class="chart-foot">${destinationSummaryHTML()}Outcome groups do not overlap. Naming and usability findings may also apply to verified destinations. A destination success rate does not establish accessibility conformance or complete coverage.</div></section><section class="panel"><div class="panel-head"><div><h2>Where to focus first</h2><p>Pages with confirmed link or name issues</p></div><button class="text-btn" data-tab="coverage">View pages ${icon('arrow')}</button></div>${affected.map(x=>`<div class="bar-row"><button data-page="${esc(x.p)}" title="${esc(x.p)}">Page: ${esc(pageLabel(x.p))}</button><div class="bar-track" aria-hidden="true"><div class="bar-fill" style="width:${x.n/Math.max(...affected.map(a=>a.n),1)*100}%"></div></div><strong title="${x.broken} broken destination(s), ${x.names} link-name issue(s)">${x.n}</strong></div><p class="focus-breakdown small">Broken destinations: ${x.broken} · Link-name issues: ${x.names}</p>`).join('')||'<p class="small">No confirmed link or name issues were recorded. Check the recorded limitation reasons and action coverage.</p>'}<div class="chart-foot">Page labels are URL paths, not failure categories. Counts combine broken destinations and link-name issues; controls outside destination checks and review notes are excluded.</div></section></div>`}

function filtered(){return audit.assets.filter(a=>hasStatus(a,filter)&&(!pageFilter||a.page===pageFilter)&&(!viewportFilter||a.viewport===viewportFilter)&&(!typeFilter||a.issues.some(i=>i.code===typeFilter))&&(`${a.name} ${a.source} ${a.accessibleName} ${a.page} ${a.issues.map(i=>i.message).join(' ')}`.toLowerCase().includes(query.toLowerCase())))}
function issueTypes(){return [...new Map(audit.assets.flatMap(a=>a.issues.map(i=>[i.code,i]))).values()]}
function findingsHTML(){return `<section class="panel findings"><div class="panel-head"><div><h2>${tab==='overview'?'Confirmed issues first':'Link inventory'}</h2><p>The default overview shows confirmed link and naming issues. Choose a result group or All links for the full inventory.</p></div><span class="small">Real browser evidence</span></div><div class="table-tools"><label class="search">${icon('search')}<input id="finding-search" aria-label="Search links or pages" placeholder="Search links or findings…" value="${esc(query)}"></label><select id="status-filter" aria-label="Filter by severity">${[['issues','All findings'],['confirmed','Confirmed link/name issues'],['all','All links'],...resultFilterEntries(),...Object.entries(labels).filter(([k])=>!['pass','unverified'].includes(k))].map(([v,l])=>`<option value="${v}" ${filter===v?'selected':''}>${l}</option>`).join('')}</select><select id="type-filter" aria-label="Filter by issue type"><option value="">Every issue type</option>${issueTypes().map(i=>`<option value="${esc(i.code)}" ${typeFilter===i.code?'selected':''}>${esc(i.code.replaceAll('-',' '))}</option>`).join('')}</select><select id="page-filter" aria-label="Filter by page"><option value="">All pages</option>${audit.pages.map(p=>`<option ${pageFilter===p?'selected':''} value="${esc(p)}">${esc(pageLabel(p))}</option>`).join('')}</select><select id="viewport-filter" aria-label="Filter by viewport"><option value="">All audited viewports</option>${auditViewports(audit).map(v=>`<option value="${v}" ${viewportFilter===v?'selected':''}>${v} Web App</option>`).join('')}</select></div><div id="rows">${rowsHTML()}</div></section>`}
function rowsHTML(){let rows=filtered(),max=Math.max(1,Math.ceil(rows.length/8));pageNum=Math.min(pageNum,max);return `<div class="table-wrap"><table><thead><tr><th scope="col">Link / destination</th><th scope="col">Findings</th><th scope="col">Page</th><th scope="col">Viewport</th><th scope="col">Evidence</th></tr></thead><tbody>${rows.slice((pageNum-1)*8,pageNum*8).map(a=>`<tr><td><div class="asset-cell"><span class="thumb">${icon(a.status==='broken'?'alert':'link')}</span><div><div class="asset-name" title="${esc(a.name)}">${esc(a.name.length>38?a.name.slice(0,35)+'…':a.name)}</div><div class="asset-meta">${a.type} · ${a.httpStatus?'HTTP '+a.httpStatus:'No HTTP verdict'}</div></div></div></td><td class="result-cell">${verificationHTML(a)}${[...new Set(a.issues.filter(i=>!['broken','unverified'].includes(i.severity)).map(i=>i.severity))].map(k=>`<span class="badge ${k} secondary-finding">${labels[k]}</span>`).join('')}</td><td title="${esc(a.page)}">${esc(pageLabel(a.page).slice(0,38))}</td><td class="small">${a.viewport}</td><td><button class="row-action" data-detail="${a.id}" aria-label="Inspect ${esc(a.name)} on ${esc(a.page)}">Inspect ${icon('chevron')}</button></td></tr>`).join('')}</tbody></table>${!rows.length?`<div class="empty">${filter==='confirmed'&&!query?'No confirmed link or naming issues in this selection. Access, response and action details are available in their own sections.':'No link observations match these filters.'}<br><button class="text-btn" data-action="clear">Clear filters</button></div>`:''}</div><div class="table-footer"><span>${rows.length?`${(pageNum-1)*8+1}–${Math.min(pageNum*8,rows.length)}`:'0'} of ${rows.length} observations</span><div class="inline"><button class="row-action" data-paginate="-1" ${pageNum===1?'disabled':''}>Previous</button><span>${pageNum} / ${max}</span><button class="row-action" data-paginate="1" ${pageNum===max?'disabled':''}>Next</button></div></div>`}
function coverageHTML(){const columns=[...Object.entries(outcomeLabels).map(([k,l])=>['outcome:'+k,l]),...Object.entries(labels).filter(([k])=>['alt','review','performance'].includes(k))];return `<section class="panel findings"><div class="panel-head"><div><h2>Page coverage</h2><p>Counts include overlapping findings and selected viewports. Select a count to inspect.</p></div><span class="badge review">Bounded exploration</span></div><div class="table-wrap"><table class="matrix"><thead><tr><th>Page</th>${columns.map(([,l])=>`<th>${l}</th>`).join('')}<th>Page responses</th><th>Viewports inspected</th></tr></thead><tbody>${audit.pages.map(p=>`<tr><td>${esc(pageLabel(p))}</td>${columns.map(([k,l])=>{let n=audit.assets.filter(a=>a.page===p&&hasStatus(a,k)).length;return `<td><button class="heat ${['outcome:broken','alt'].includes(k)&&n?'issue':''} ${['outcome:incomplete','outcome:manual'].includes(k)?'neutral-heat':''}" data-cell="${esc(p)}" data-status="${k}" aria-label="${l} on ${esc(p)}: ${n}">${n}</button></td>`}).join('')}<td>${audit.pageResults.filter(x=>x.url===p).map(x=>`${esc(x.viewport)}: ${x.httpStatus?'HTTP '+x.httpStatus:'No response'} · ${esc(x.status==='unverified'?'Check limitation':x.status)}`).join('<br>')}</td><td>${audit.pageResults.filter(x=>x.url===p&&x.status==='checked').length} / ${auditViewports(audit).length}</td></tr>`).join('')}</tbody></table></div></section><section class="panel section-space"><h2>Coverage notes and page-check limitations</h2><p class="small">A completed scan does not prove that all possible application states were reached.</p>${audit.coverage.gaps.map(g=>`<details class="gap"><summary>${esc(g.reason)} <span class="small">${esc(pageLabel(g.page))}</span></summary><p class="small">${esc(g.detail||g.page)}</p></details>`).join('')||'<p>No traversal errors were recorded. Closed shadow roots, canvas semantics and undiscovered interaction paths still require contextual review.</p>'}</section>`}
function bindMain(){if($('#theme-select'))$('#theme-select').onchange=e=>window.lensTheme.set(e.target.value);if($('#start-audit-form'))$('#start-audit-form').onsubmit=e=>{e.preventDefault();openSetup($('#start-url').value.trim())};document.querySelectorAll('[data-delete-history]').forEach(b=>b.onclick=()=>deleteHistory(b.dataset.deleteHistory));document.querySelectorAll('[data-action]').forEach(b=>b.onclick=e=>{e.preventDefault();let a=b.dataset.action;if(a==='home'){view='home';render();$('#main').focus({preventScroll:true})}if(a==='new')openSetup();if(a==='clear-history')deleteHistory();if(a==='export')openExport();if(a==='history'){view='history';render()}if(a==='audit'){view='audit';render()}if(a==='clear'){filter='all';query='';pageFilter='';typeFilter='';viewportFilter='';pageNum=1;render()}});document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;pageNum=1;if(tab==='findings')filter='all';render();$(`#tab-${tab}`)?.focus({preventScroll:true})});document.querySelectorAll('[role=tab]').forEach((b,i)=>b.onkeydown=e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();let n=e.key==='Home'?0:e.key==='End'?2:(i+(e.key==='ArrowRight'?1:2))%3;document.querySelectorAll('[role=tab]')[n].click()}});document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;typeFilter='';viewportFilter='';tab='findings';pageNum=1;render()});document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{pageFilter=b.dataset.page;filter='confirmed';typeFilter='';viewportFilter='';tab='findings';pageNum=1;render()});document.querySelectorAll('[data-cell]').forEach(b=>b.onclick=()=>{pageFilter=b.dataset.cell;filter=b.dataset.status;typeFilter='';viewportFilter='';tab='findings';pageNum=1;render()});if($('#finding-search')){$('#finding-search').oninput=e=>{query=e.target.value;pageNum=1;refreshRows()};$('#status-filter').onchange=e=>{filter=e.target.value;pageNum=1;refreshRows()};$('#type-filter').onchange=e=>{typeFilter=e.target.value;pageNum=1;refreshRows()};$('#viewport-filter').onchange=e=>{viewportFilter=e.target.value;pageNum=1;refreshRows()};$('#page-filter').onchange=e=>{pageFilter=e.target.value;pageNum=1;refreshRows()}}bindRows();document.querySelectorAll('[data-history]').forEach(b=>b.onclick=()=>{audit=saved[+b.dataset.history];view='audit';tab='overview';filter='confirmed';query='';pageFilter='';typeFilter='';viewportFilter='';render()});}
function refreshRows(){$('#rows').innerHTML=rowsHTML();bindRows()}
function bindRows(){document.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>openDetail(b.dataset.detail));document.querySelectorAll('[data-paginate]').forEach(b=>b.onclick=()=>{pageNum+=+b.dataset.paginate;refreshRows()});document.querySelector('[data-action="clear"]')?.addEventListener('click',()=>{filter='all';query='';pageFilter='';typeFilter='';viewportFilter='';render()})}
function modal(title,body,foot=''){const d=$('#dialog');d.innerHTML=`<header class="dialog-head"><h2 id="dialog-title">${title}</h2><button class="close" aria-label="Close dialog">${icon('close')}</button></header><div class="dialog-body">${body}</div>${foot?`<footer class="dialog-foot">${foot}</footer>`:''}`;if(!d.open)d.showModal();d.querySelector('.close').onclick=()=>d.close();}
function openDetail(id){const a=audit.assets.find(x=>x.id===id);modal('Link evidence',`${verificationHTML(a)}<h3 class="section-space">${esc(a.name)}</h3><dl>${[['Page',a.page],['Destination',a.source||'None'],['Final URL',a.finalURL||'Not verified'],['HTTP status',a.httpStatus||'Unavailable'],['Viewport / state',a.viewport+' · '+a.state],['Selector',a.selector],['Link text',a.text||'Empty'],['Accessible name',a.accessibleName||'Missing'],['Target',a.target||'Same browsing context'],['Relationship',a.rel||'None'],['Verification',a.reason||(a.verification==='browser-session'?'Checked in the browser session':a.verification||'See findings')]].map(([k,v])=>`<dt>${esc(k)}</dt><dd>${esc(v)}</dd>`).join('')}</dl><h3>Validation findings</h3>${a.issues.map(i=>`<section class="finding-detail"><span class="badge ${i.severity}">${i.severity==='unverified'?esc(verificationResult(a).label):labels[i.severity]}</span><p><strong>${esc(i.message)}</strong></p><p class="small">${esc(i.fix)}</p></section>`).join('')||'<p>No automatic failure detected. Review whether the name accurately describes the destination.</p>'}<h3 class="section-space">Recorded markup</h3><pre>${esc(a.html)}</pre>`,`<span class="small">Actual browser observation</span><button id="related" class="primary">View related occurrences</button>`);$('#related').onclick=()=>{$('#dialog').close();query=a.name;filter='all';pageFilter='';typeFilter='';viewportFilter='';tab='findings';pageNum=1;render()}}
function openSetup(url=''){setup={url,access:'public',sessionId:null,signed:false,scope:'all',viewports:['Desktop','Mobile'],selected:new Set(),paths:[],discovered:false,search:'',step:1,gaps:[]};setupUI()}
function selectedPages(){return setup.scope==='current'?[setup.url]:setup.scope==='all'?setup.paths:[...setup.selected]}
function steps(){return `<div class="steps" aria-label="Audit setup steps">${['Website & access','Choose pages','Review & run'].map((t,i)=>`<span class="${setup.step===i+1?'active':''}" ${setup.step===i+1?'aria-current="step"':''}>${i+1}. ${t}</span>`).join('')}</div>`}
function setupUI(){let body=steps();if(setup.step===1){body+=`<div class="field"><label for="site-url">Website or current page URL</label><input id="site-url" type="url" value="${esc(setup.url)}" placeholder="https://your-website.com"><span class="small">Paste a specific page URL for a current-page audit.</span><span id="url-error" class="error" role="alert"></span></div><h3>Access method</h3><div class="choice-grid" style="grid-template-columns:1fr 1fr">${[['public','Public website','Pages available without signing in.'],['private','Requires sign-in','Keep a real authenticated browser session.']].map(([v,l,s])=>`<label class="choice ${setup.access===v?'selected':''}"><input type="radio" name="access" value="${v}" ${setup.access===v?'checked':''}><span><strong>${l}</strong><small>${s}</small></span></label>`).join('')}</div>${setup.access==='private'?`<div class="coverage-note">${icon('lock')}<span>Sign in directly in the browser window. Return here and confirm when the application is ready. The sign-in window closes once connected. Discovery and link checks run headlessly, with no visible browser windows or tabs. Credentials are not entered into LinkLens.</span></div><button id="sign-in" class="btn-icon">${icon(setup.signed?'check':'lock')}${setup.signed?'Session connected':setup.sessionId?'Confirm completed sign-in':'Open sign-in browser'}</button>`:''}<p class="small section-space">The scanner runs in the background and visits pages and supported disclosure controls. Use an appropriate account for authenticated environments; automatic exploration avoids forms and known action requests.</p>`}else if(setup.step===2){body+=`<h3>Choose your audit scope</h3><p class="small">Entire website explores across this website, not just the current URL path. Current page remains a single-page audit.</p><div class="choice-grid">${[['current','Current page','Only the URL you entered.'],['all','Entire website','Automatically explore the site homepage, signed-in page, menus and reachable same-site pages.'],['selected','Select pages','Choose pages or whole sections.']].map(([v,l,s])=>`<label class="choice ${setup.scope===v?'selected':''}"><input type="radio" name="scope" value="${v}" ${setup.scope===v?'checked':''}><span><strong>${l}</strong><small>${s}</small></span></label>`).join('')}</div>${setup.scope==='current'?`<div class="page-list"><div class="page-item">${icon('file')}<span>${esc(setup.url)}</span></div></div>`:`<div class="inline between"><span class="small">${setup.paths.length} pages discovered across the website</span>${setup.scope==='selected'?'<div><button id="select-all" class="text-btn">Select all</button><button id="select-none" class="text-btn">Clear</button></div>':''}</div>${setup.discovered?'<button id="discover" class="text-btn">Refresh website discovery</button>':`<button id="discover" class="btn-icon">${icon('search')} Discover website pages</button><p class="small">Starts from the site homepage and your signed-in page, then follows same-site links and supported menu navigation across paths. Up to 200 pages; unreachable states and limits are reported.</p>`}${setup.scope==='selected'?`<input id="page-search" style="width:100%" placeholder="Search pages or sections…" aria-label="Search discovered pages" value="${esc(setup.search)}"><div class="inline" style="flex-wrap:wrap;margin-top:8px">${[...new Set(setup.paths.map(p=>'/'+new URL(p).pathname.split('/')[1]).filter(p=>p!=='/'))].slice(0,8).map(p=>`<button class="text-btn" data-section="${esc(p)}">Select ${esc(p)}</button>`).join('')}</div>`:''}<div class="page-list" id="select-pages">${pageChoices()}</div>${setup.scope==='selected'?`<details><summary class="small" style="cursor:pointer">Add specific page URLs</summary><div class="field section-space"><label for="manual-pages">Same-site URLs or paths, one per line</label><textarea id="manual-pages" rows="3" placeholder="/contact&#10;/products"></textarea><span id="manual-error" class="error" role="alert"></span><button id="add-pages">Add pages</button></div></details>`:''}`}<div class="small" id="selection-count">${selectedPages().length} pages selected</div>${setup.gaps.length?`<p class="small">${setup.gaps.length} discovery notes will be included in the audit report.</p>`:''}`}else{body+=`<h3>Ready to look closer.</h3><fieldset class="field"><legend>Choose viewports</legend><div class="choice-grid">${[['Desktop','Desktop Web App','1366 × 900'],['Mobile','Mobile Web App','390 × 844']].map(([v,l,size])=>`<label class="choice"><input type="checkbox" name="audit-viewport" value="${v}" ${(setup.viewports||['Desktop','Mobile']).includes(v)?'checked':''}><span><strong>${l}</strong><small>${size}</small></span></label>`).join('')}</div><p id="viewport-error" class="error" role="alert"></p></fieldset><p>${selectedPages().length} pages on <strong>${esc(new URL(setup.url).hostname)}</strong></p><div class="check-grid">${['Selected viewports','Destination HTTP status','Lazy-loaded links','Anchors & ARIA links','Link text & accessible names','Fragments & keyboard access','Redirects & special protocols','Supported disclosures & tabs'].map(t=>`<div class="check-item">${icon('check')}${t}</div>`).join('')}</div><div class="coverage-note">${icon('info')}<span>Closed shadow roots, unrecognized interactions, and exhaustive carousel journeys cannot be guaranteed. Timeouts and traversal limits are recorded explicitly.</span></div>`}modal('New link audit',body,`<button id="back">${setup.step===1?'Cancel':'Back'}</button><button id="next" class="primary btn-icon">${setup.step===3?'Run link audit':setup.step===1?'Choose pages':setup.scope==='all'&&!setup.discovered?'Discover entire website':'Review audit'} ${icon('arrow')}</button>`);document.querySelectorAll('[name=audit-viewport]').forEach(e=>e.onchange=()=>{setup.viewports=[...document.querySelectorAll('[name=audit-viewport]:checked')].map(e=>e.value)});$('#back').onclick=()=>{if(setup.step===1)$('#dialog').close();else{setup.step--;setupUI()}};$('#next').onclick=async()=>{if(setup.step===1){const old=setup.url;setup.url=$('#site-url').value.trim();try{const u=new URL(setup.url);if(!['http:','https:'].includes(u.protocol)||u.username||u.password)throw 0;setup.url=u.href}catch{$('#url-error').textContent='Enter a valid HTTP or HTTPS URL without embedded credentials.';return}if(setup.sessionId&&new URL(old).origin!==new URL(setup.url).origin){setup.signed=false;setup.sessionId=null;}if(old!==setup.url){setup.paths=[];setup.discovered=false;setup.selected=new Set();setup.gaps=[];}if(setup.access==='private'&&!setup.signed){$('#url-error').textContent='Complete browser sign-in before continuing.';return}}if(setup.step===2&&setup.scope==='all'&&!setup.discovered){setup.reviewAfterDiscovery=true;runDiscovery();return}if(setup.step===2&&(!selectedPages().length||selectedPages().length>200)){toast('Select between 1 and 200 pages.');return}if(setup.step===3){setup.viewports=[...document.querySelectorAll('[name=audit-viewport]:checked')].map(e=>e.value);if(!setup.viewports.length){$('#viewport-error').textContent='Select at least one viewport.';return}runAudit();return}setup.step++;setupUI()};document.querySelectorAll('[name=access]').forEach(x=>x.onchange=()=>{setup.url=$('#site-url').value;setup.access=x.value;setupUI()});$('#sign-in')?.addEventListener('click',async e=>{const b=e.currentTarget;b.disabled=true;try{if(!setup.sessionId){setup.url=$('#site-url').value.trim();const result=await api('sessions',{url:setup.url});setup.sessionId=result.id;toast('Sign in in the browser, then return to confirm.')}else{const connected=await api(`sessions/${setup.sessionId}/confirm`,{});if(connected.chooseApplication){chooseApplication(connected.pages);return}setup.url=connected.url;setup.signed=true;}setupUI()}catch(e){$('#url-error').textContent=e.message;b.disabled=false}});document.querySelectorAll('[name=scope]').forEach(x=>x.onchange=()=>{setup.scope=x.value;setupUI()});$('#discover')?.addEventListener('click',()=>runDiscovery());$('#page-search')?.addEventListener('input',e=>{setup.search=e.target.value;$('#select-pages').innerHTML=pageChoices();bindPageChoices()});$('#select-all')?.addEventListener('click',()=>{setup.paths.forEach(p=>setup.selected.add(p));setupUI()});$('#select-none')?.addEventListener('click',()=>{setup.selected.clear();setupUI()});document.querySelectorAll('[data-section]').forEach(b=>b.onclick=()=>{setup.paths.filter(p=>{let path=new URL(p).pathname;return path===b.dataset.section||path.startsWith(b.dataset.section+'/')}).forEach(p=>setup.selected.add(p));setupUI()});$('#add-pages')?.addEventListener('click',()=>{let entries=$('#manual-pages').value.split('\n').map(x=>x.trim()).filter(Boolean),parsed=[];try{if(!entries.length)throw 0;for(let p of entries){let u=new URL(p,setup.url);if(u.origin!==new URL(setup.url).origin||u.username||u.password)throw 0;parsed.push(u.href)}}catch{$('#manual-error').textContent='Enter paths or URLs from the same website.';return}parsed.forEach(p=>{if(!setup.paths.includes(p))setup.paths.push(p);setup.selected.add(p)});setupUI()});bindPageChoices()}
function pageChoices(){let pages=setup.paths.filter(p=>p.toLowerCase().includes(setup.search.toLowerCase()));return pages.length?pages.map(p=>`<label class="page-item"><input type="checkbox" data-select="${esc(p)}" ${setup.scope==='all'||setup.selected.has(p)?'checked':''} ${setup.scope==='all'?'disabled':''}><span>${esc(pageLabel(p))}</span></label>`).join(''):'<div class="empty">No pages to display.</div>'}
function bindPageChoices(){document.querySelectorAll('[data-select]').forEach(c=>c.onchange=()=>{c.checked?setup.selected.add(c.dataset.select):setup.selected.delete(c.dataset.select);$('#selection-count').textContent=`${selectedPages().length} pages selected`})}
function readHistory(){try{return JSON.parse(localStorage.getItem('linklense-audits-v1')||'[]').filter(a=>a.sampleData===false&&Array.isArray(a.assets));}catch{return[]}}
function saveAudit(result){audit=result;const records=[audit,...readHistory()];saved=[...new Map(records.map(a=>[a.id,a])).values()].sort((a,b)=>b.date.localeCompare(a.date)).slice(0,10);storageWarning='';try{localStorage.setItem('linklense-audits-v1',JSON.stringify(saved))}catch{storageWarning='Browser storage is full or unavailable.'}}
function finishDiscovery(result){setup.paths=result.pages.map(p=>p.url);setup.selected=new Set(setup.paths);setup.gaps=result.gaps;setup.discovered=true;if(setup.reviewAfterDiscovery&&setup.paths.length)setup.step=3;setup.reviewAfterDiscovery=false;setupUI();toast(`Discovered ${setup.paths.length} pages.`)}
async function finishAudit(result){result.coverage.gaps.unshift(...setup.gaps);result.unverified=result.coverage.gaps.length;if(navigator.locks){await navigator.locks.request('linklense-history',()=>saveAudit(result))}else saveAudit(result);$('#dialog').close();view='audit';tab='overview';filter='confirmed';query='';pageFilter='';typeFilter='';viewportFilter='';pageNum=1;render();toast(storageWarning?'Audit complete. Export this unsaved report to keep it.':`Audit complete: ${audit.assets.length} link observations.`)}
function rememberJob(kind,input){try{sessionStorage.setItem('linklense-active-job',JSON.stringify({kind,input,setup:{...setup,selected:[...setup.selected]}}))}catch{toast('Scan progress cannot be restored after a refresh in this browser.')}}
function forgetJob(){try{sessionStorage.removeItem('linklense-active-job')}catch{}}
async function runJob(kind,resume=null){const input=resume?.input||{kind,url:setup.url,requestId:crypto.randomUUID(),sessionId:setup.access==='private'?setup.sessionId:null,pages:kind==='scan'?selectedPages():undefined,viewports:setup.viewports||['Desktop','Mobile'],scope:{all:'Entire website (discovered pages)',current:'Current page',selected:'Selected pages'}[setup.scope]};let token={id:input.requestId,cancelled:false};activeJob=token;rememberJob(kind,input);modal(kind==='discover'?'Discovering website pages':'Inspecting website links',`<h3 id="scan-stage">${resume?'Reconnecting to your audit…':'Starting browser…'}</h3><div class="progress-track" role="progressbar" aria-valuemin="0" aria-valuemax="100" aria-label="Audit progress"><div class="progress-fill" style="width:2%"></div></div><p class="small" id="scan-progress" aria-live="polite">Preparing your ${setup.access==='private'?'signed-in':'public'} browser session.</p><p class="small">You can refresh this tab and reconnect to this audit.</p>`,`<span class="small">Live browser inspection</span><button id="cancel-scan">Cancel</button>`);$('#cancel-scan').onclick=()=>$('#dialog').close();try{const job=await api('jobs',input);token.id=job.id;if(token.cancelled){await api('jobs/'+job.id,null,'DELETE');return}let retries=0;while(!token.cancelled){let data;try{data=await api('jobs/'+job.id);retries=0}catch(e){if(token.cancelled)return;if(++retries>5)throw e;$('#scan-stage').textContent='Connection interrupted. Reconnecting…';await new Promise(r=>setTimeout(r,1000));continue;}if(token.cancelled)return;if(data.status==='error')throw Error(data.error);if(data.status==='cancelled')throw Error('The audit was cancelled.');if(data.status==='complete'){activeJob=null;forgetJob();await(kind==='discover'?finishDiscovery:finishAudit)(data.result);return}let p=data.progress;$('#scan-stage').textContent=p.message;$('#scan-progress').textContent=`${p.done||0} of ${p.total||'…'} ${kind==='scan'?'page / viewport checks':'discovery candidates'} · ${p.links||0} link observations${p.linkChecks?` · Checking destinations: ${p.linkChecks.completed}/${p.linkChecks.total}`:''}`;$('.progress-fill').style.width=(p.total?Math.max(2,p.done/p.total*100):2)+'%';if(p.total)$('.progress-track').setAttribute('aria-valuenow',String(Math.round(p.done/p.total*100)));else $('.progress-track').removeAttribute('aria-valuenow');await new Promise(r=>setTimeout(r,650));}}catch(e){if(token.cancelled)return;activeJob=null;const sessionError=/session|sign.in|browser.*closed/i.test(e.message);if(sessionError){forgetJob();setup.sessionId=null;setup.signed=false;setup.step=1;}else activeJob=token;modal('Unable to complete the audit',`<p class="error">${esc(e.message)}</p><p class="small">Your previous report is unchanged. ${sessionError?'Reconnect your sign-in session; page selections are retained.':'Reconnect to the existing job or return to setup.'}</p>`,`<button id="retry">Back to setup</button>${sessionError?'':'<button id="reconnect" class="primary">Reconnect to audit</button>'}`);$('#retry').onclick=()=>{activeJob=null;api('jobs/'+token.id,null,'DELETE').catch(()=>{});forgetJob();setupUI()};$('#reconnect')?.addEventListener('click',()=>runJob(kind,{input}));}}
function runDiscovery(){runJob('discover')}
function runAudit(){runJob('scan')}
$('#dialog').addEventListener('close',()=>{if(activeJob){forgetJob();activeJob.cancelled=true;if(activeJob.id)api('jobs/'+activeJob.id,null,'DELETE').catch(()=>{});activeJob=null;setup.sessionId=null;setup.signed=false;toast('Audit cancelled. Browser inspection stopped.')}else if(setup.sessionId){api('sessions/'+setup.sessionId,null,'DELETE').catch(()=>{});setup.sessionId=null;setup.signed=false;}});
function historyHTML(){return `<div class="heading"><div><button class="text-btn" data-action="home">← Back to home</button><h1>Scan history</h1><p>Your audits, saved in this browser.</p></div><div class="actions">${saved.length?'<button data-action="clear-history">Clear history</button>':''}<button class="primary btn-icon" data-action="new">${icon('plus')} New audit</button></div></div>${!saved.length?`<section class="panel empty"><h2>No audits yet.</h2><p>Run a link audit to create your first report.</p><button data-action="home">Go to home</button></section>`:`<section class="panel findings"><div class="table-wrap"><table><thead><tr><th>Website</th><th>Date</th><th>Scope</th><th>Observations</th><th>Report</th></tr></thead><tbody>${saved.map((a,i)=>`<tr><td>${esc(new URL(a.url).hostname)}</td><td>${new Date(a.date).toLocaleString()}</td><td>${a.pages.length} pages · ${esc(a.scope)}</td><td>${a.assets.length}</td><td><button class="row-action" data-history="${i}">Open report ${icon('arrow')}</button><button class="row-action" data-delete-history="${esc(a.id)}" aria-label="Delete report for ${esc(new URL(a.url).hostname)} from ${esc(new Date(a.date).toLocaleString())}">Delete</button></td></tr>`).join('')}</tbody></table></div></section>`}`}
function deleteHistory(id){
 const selected=saved.filter(a=>!id||a.id===id),ids=new Set(selected.map(a=>a.id));
 modal(id?'Delete this report?':'Clear scan history?',`<p>${id?`Delete the saved audit for <strong>${esc(selected[0]?new URL(selected[0].url).hostname:'this website')}</strong>?`:`Delete the ${ids.size} reports currently listed in scan history?`} Exported files are unaffected.</p><p id="delete-error" class="error" role="alert"></p>`,`<button id="delete-cancel">Cancel</button><button id="delete-confirm" class="primary">${id?'Delete report':'Clear history'}</button>`);
 $('#delete-cancel').onclick=()=>$('#dialog').close();
 $('#delete-confirm').onclick=async()=>{
  try{const remove=()=>{const next=readHistory().filter(a=>!ids.has(a.id));localStorage.setItem('linklense-audits-v1',JSON.stringify(next));saved=next;if(audit&&ids.has(audit.id)){audit=saved[0]||null;storageWarning='';}};
   if(navigator.locks)await navigator.locks.request('linklense-history',remove);else remove();
   $('#dialog').close();render();toast(id?'Report deleted.':'Scan history cleared.');
  }catch{$('#delete-error').textContent='History could not be updated. Your reports have not been removed.';}
 };
}
function reportRuntime(){const root=document.querySelector('#report-data');const data=JSON.parse(root.textContent),rows=[...document.querySelectorAll('tbody tr')];const q=document.querySelector('#q'),severity=document.querySelector('#severity'),type=document.querySelector('#issue-type'),page=document.querySelector('#report-page'),vp=document.querySelector('#viewport');function apply(){let n=0;rows.forEach((r,i)=>{const a=data.assets[i],show=(!q.value||r.textContent.toLowerCase().includes(q.value.toLowerCase()))&&(!severity.value||(severity.value.startsWith('outcome:')?a.verificationResult.group===severity.value.slice(8):severity.value==='pass'?a.issues.length===0:a.issues.some(f=>f.severity===severity.value)))&&(!type.value||a.issues.some(f=>f.code===type.value))&&(!page.value||a.page===page.value)&&(!vp.value||a.viewport===vp.value);r.hidden=!show;if(show)n++;});document.querySelector('#visible-count').textContent=`${n} of ${rows.length} link observations`;document.querySelector('#no-results').hidden=n!==0;document.querySelectorAll('[data-category]').forEach(b=>{b.setAttribute('aria-pressed',b.dataset.category===severity.value);});}for(const el of[q,severity,type,page,vp])el.addEventListener(el===q?'input':'change',apply);document.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{severity.value=severity.value===b.dataset.category?'':b.dataset.category;apply()});document.querySelector('#reset').onclick=()=>{for(const el of[q,severity,type,page,vp])el.value='';apply()};document.querySelector('#expand').onclick=()=>rows.filter(r=>!r.hidden).forEach(r=>r.querySelectorAll('details').forEach(d=>d.open=true));document.querySelector('#collapse').onclick=()=>document.querySelectorAll('tbody details').forEach(d=>d.open=false);document.querySelector('#download-filtered').onclick=()=>{const cell=v=>'"'+String(v??'').replace(/^\s*[=+@-]/,"'$&").replaceAll('"','""')+'"';const content=[['resource','page','viewport','issues','accessibleName','selector','verificationGroup','verificationReason','verificationNextStep'].join(','),...data.assets.filter((a,i)=>!rows[i].hidden).map(a=>[a.source,a.page,a.viewport,a.issues.map(i=>i.code).join('; '),a.accessibleName,a.selector,a.verificationResult.group,a.verificationResult.label,a.verificationResult.next].map(cell).join(','))].join('\r\n');const u=URL.createObjectURL(new Blob([content],{type:'text/csv'}));const a=document.createElement('a');a.href=u;a.download='linklense-filtered.csv';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)};document.querySelector('#print').onclick=()=>window.print();apply();}
function reportHTML(){const exportLabels={...Object.fromEntries(Object.entries(outcomeLabels).map(([k,l])=>[k==='broken'?'broken':'outcome:'+k,l])),alt:labels.alt,review:labels.review,performance:labels.performance};const counts=Object.fromEntries(Object.keys(exportLabels).map(k=>[k,audit.assets.filter(a=>hasStatus(a,k)).length]));const data=JSON.stringify({assets:audit.assets.map(a=>({...a,verificationResult:verificationResult(a)}))}).replaceAll('<','\\u003c');return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>LinkLens · ${esc(new URL(audit.url).hostname)}</title><style>:root{font-family:system-ui,sans-serif;color:#252332;background:#f6f6fa}*{box-sizing:border-box}body{max-width:1250px;margin:0 auto;padding:38px 25px}h1{font-size:32px;letter-spacing:-1px}h2{font-size:20px}p{line-height:1.65;color:#615d6d}.meta{font-size:13px}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin:25px 0}.cards button{text-align:left;padding:16px;background:white;min-width:0}.cards strong{display:block;font-size:26px;margin:8px 0}.cards button[aria-pressed=true]{outline:2px solid #5145b8;background:#f0edfd}.bar{height:5px;background:#5145b8;margin-top:15px;border-radius:2px}.toolbar{display:flex;gap:10px;flex-wrap:wrap;padding:20px;background:white;border:1px solid #ddd9e8;border-radius:10px;margin:20px 0}.toolbar input{flex:1;min-width:180px}input,select,button{font:inherit;border:1px solid #cbc7d7;border-radius:6px;padding:10px;background:white;color:#302c3d}button{cursor:pointer}button:hover{background:#f1edf9}:focus-visible{outline:3px solid #6a5bcb;outline-offset:2px}.controls{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin:20px 0;font-size:12px}table{border-collapse:collapse;width:100%;font-size:12px;background:white}th,td{padding:14px;border-bottom:1px solid #ddd9e8;text-align:left;vertical-align:top;overflow-wrap:anywhere}th{background:#efedf5}td:first-child{width:25%;max-width:300px}small{display:block;color:#686271;margin-top:6px}.badge{display:inline-block;padding:4px 7px;border-radius:4px;background:#efedf6;margin:0 4px 4px 0;font-size:11px}.broken,.alt{background:#f9e9e8;color:#96353e}.review,.unverified{background:#efebfa;color:#58428d}.pass{background:#e6f2ed;color:#27694f}details{margin:12px 0}summary{cursor:pointer;font-weight:600}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#f5f3fa;padding:12px;border-radius:5px;max-width:550px}.failed-pages{display:flex;gap:10px;overflow-wrap:anywhere}.failed-pages .icon{width:19px;height:19px;flex-shrink:0;fill:none;stroke:currentColor;stroke-width:1.7}.coverage{border:1px solid #dcd5eb;border-radius:9px;background:#f1edf8;padding:16px;margin:20px 0}.finding{padding:10px 0;border-bottom:1px solid #eee}.table-scroll{overflow:auto}#no-results{text-align:center;padding:30px}@media(max-width:700px){.cards{grid-template-columns:repeat(2,1fr)}body{padding:20px 14px}.toolbar select{max-width:100%}.table-scroll table{min-width:750px}}@media print{body{padding:0;background:white;font-size:10px}.toolbar,.controls,button#print{display:none}.cards{grid-template-columns:repeat(3,1fr)}.cards button{border:1px solid #ccc}.table-scroll{overflow:visible}table{font-size:9px}th,td{padding:6px}tr{break-inside:avoid}details{display:block}details>*{display:block!important}details::details-content{content-visibility:visible!important;height:auto!important}pre{max-width:300px}.coverage{break-inside:avoid}}.verification-reason,.verification-next{font-size:12px;line-height:1.6;margin:6px 0}.verification-evidence{margin-bottom:10px}</style></head><body><main><h1>LinkLens</h1><h2>Link integrity audit</h2><p class="meta">${esc(audit.url)}<br>${new Date(audit.date).toLocaleString()} · ${esc(audit.scope)} · ${audit.pages.length} pages · ${viewportLabel(audit)} · ${audit.access==='private'?'Authenticated':'Public'} access</p>${failedPagesHTML()}${destinationSummaryHTML()}<div class="cards">${Object.entries(counts).map(([k,n])=>`<button data-category="${k}" aria-pressed="false"><span>${exportLabels[k]}</span><strong>${n}</strong><div class="bar" style="width:${n/(audit.assets.length||1)*100}%;background:${colors[k]}"></div></button>`).join('')}</div><p class="meta">${audit.assets.length} observations · ${audit.coverage.uniqueResources} unique destinations. Categories overlap when one link has multiple findings. Select a category to filter.</p><section class="coverage"><strong>Coverage and interpretation</strong><p class="meta">${esc(audit.coverage.note)} Automated passes are not a claim of accessibility conformance. ${audit.unverified} coverage notes.</p><details><summary>View coverage notes and limits</summary>${audit.coverage.gaps.map(g=>`<p class="meta"><strong>${esc(g.reason)}</strong> · ${esc(g.page)}<br>${esc(g.detail)}</p>`).join('')||'<p>No traversal errors recorded.</p>'}<pre>${esc(JSON.stringify(audit.coverage.limits,null,2))}</pre></details></section><div class="toolbar"><input id="q" aria-label="Search report" placeholder="Search link, issue, or evidence…"><select id="severity" aria-label="Filter by category"><option value="">All categories</option>${Object.entries(exportLabels).map(([k,l])=>`<option value="${k}">${l}</option>`).join('')}</select><select id="issue-type" aria-label="Filter by issue type"><option value="">All issue types</option>${issueTypes().map(i=>`<option value="${esc(i.code)}">${esc(i.code.replaceAll('-',' '))}</option>`).join('')}</select><select id="report-page" aria-label="Filter by page"><option value="">All pages</option>${audit.pages.map(p=>`<option value="${esc(p)}">${esc(pageLabel(p))}</option>`).join('')}</select><select id="viewport" aria-label="Filter by viewport"><option value="">All audited viewports</option><option>Desktop</option><option>Mobile</option></select><button id="reset">Clear filters</button></div><div class="controls"><strong id="visible-count" role="status"></strong><button id="expand">Expand visible evidence</button><button id="collapse">Collapse evidence</button><button id="download-filtered">Export filtered CSV</button><button id="print">Print filtered report</button></div><div class="table-scroll"><table><thead><tr><th>Link / page</th><th>Findings</th><th>Viewport & evidence</th></tr></thead><tbody>${audit.assets.map(a=>`<tr><td><strong>${esc(a.name)}</strong><small>${esc(a.page)}</small><small>${esc(a.type)}</small></td><td>${verificationHTML(a)}${a.issues.length?a.issues.filter(i=>i.severity!=='unverified').map(i=>`<div class="finding"><span class="badge ${i.severity}">${esc(i.code)}</span><div>${esc(i.message)}</div><small>Next step: ${esc(i.fix)}</small></div>`).join(''):'<span class="badge pass">Passed automated checks</span>'}</td><td>${a.viewport} · ${esc(a.state)}<details><summary>Inspect evidence</summary><p>Destination: ${esc(a.source||'No destination')}</p><p>Destination outcome: ${esc(verificationResult(a).label)} · HTTP: ${a.httpStatus||'unavailable'}</p><p>Destination: ${esc(a.finalURL||a.source||'none')}</p><p>Accessible name: ${esc(a.accessibleName||a.parentName||'none recorded')}</p><p>Tooltip: ${esc(a.tooltip||'none')}</p><p>Selector: ${esc(a.selector)}</p><pre>${esc(a.html)}</pre>${a.variantResults.map(v=>`<p>${v.loaded?'Decoded':'Not decoded'}: ${esc(v.url)}</p>`).join('')}</details></td></tr>`).join('')}</tbody></table></div><p id="no-results" hidden>No observations match these filters.</p><p class="meta">Generated by LinkLens. This report is self-contained and makes no external requests.</p></main><script type="application/json" id="report-data">${data}</script><script>(${reportRuntime.toString()})();</script></body></html>`}
function download(content,ext,mime){let url=URL.createObjectURL(content instanceof Blob?content:new Blob([content],{type:mime}));const a=document.createElement('a');a.href=url;a.download=`linklense-${new URL(audit.url).hostname}-${audit.date.slice(0,10)}.${ext}`;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);toast(`${ext.toUpperCase()} report downloaded.`)}
function openExport(){modal('Export your report',`<p style="margin:0 0 20px">Share the full audit with every observation, issue, and coverage note.</p><div class="report-options">${[['html','Interactive HTML','Category charts, issue filters, page and viewport filters, expandable evidence, and filtered CSV export.'],['pdf','PDF report','A downloadable print-ready report with all findings and evidence.'],['csv','CSV spreadsheet','Every occurrence with all issue codes, pages, and selectors.'],['json','JSON evidence','Complete structured results and coverage details.']].map(([v,l,s])=>`<button data-export="${v}">${icon('file')}<span>${l}<small>${s}</small></span>${icon('download')}</button>`).join('')}</div><p id="export-error" class="error" role="alert"></p><p class="small section-space">Full-audit exports ignore dashboard filters. Use the HTML report to share a filtered view.</p>`);document.querySelectorAll('[data-export]').forEach(b=>b.onclick=async()=>{let type=b.dataset.export;try{if(type==='html')download(reportHTML(),'html','text/html');if(type==='json')download(JSON.stringify({...audit,verificationSummary:destinationSummary(audit.assets),assets:audit.assets.map(a=>({...a,verificationResult:verificationResult(a)}))},null,2),'json','application/json');if(type==='csv'){let keys=['name','source','page','viewport','status','accessibleName','selector','bytes'];const cell=v=>'"'+String(v??'Missing').replace(/^\s*[=+@-]/,"'$&").replaceAll('"','""')+'"';download([[...keys,'verificationGroup','verificationReason','verificationNextStep','issueCodes','coverageNote'].join(','),...audit.assets.map(a=>[...keys.map(k=>a[k]),verificationResult(a).group,verificationResult(a).label,verificationResult(a).next,a.issues.map(i=>i.code).join('; '),audit.coverage.note].map(cell).join(','))].join('\r\n'),'csv','text/csv')}if(type==='pdf'){b.disabled=true;b.querySelector('small').textContent='Generating PDF…';const res=await fetch('/api/pdf',{method:'POST',headers:{'Content-Type':'application/json','X-LinkLense':'1','X-LinkLense-Build':CLIENT_BUILD_ID},body:JSON.stringify({html:reportHTML()})});if(!res.ok)throw Error((await res.json()).error);download(await res.blob(),'pdf','application/pdf');b.disabled=false;b.querySelector('small').textContent='Download another copy';}}catch(e){$('#export-error').textContent=e.message;b.disabled=false}})}
render();

window.addEventListener('storage',e=>{if(e.key==='linklense-audits-v1'){saved=readHistory();if(audit&&!storageWarning&&!saved.some(a=>a.id===audit.id))audit=saved[0]||null;if(['history','home'].includes(view)&&!$('#dialog').open)render();}});
try{const pending=JSON.parse(sessionStorage.getItem('linklense-active-job')||'null');if(pending?.input?.requestId){setup={...pending.setup,selected:new Set(pending.setup.selected)};runJob(pending.kind,pending)}}catch{forgetJob()}

function chooseApplication(pages){
 modal('Choose your signed-in application',`<p>Sign-in opened another tab or changed the website address. Choose the application you want to audit.</p><div class="report-options">${pages.map((p,i)=>`<button data-application="${i}"><span>${esc(p.title||'Application tab')}<small>${esc(p.url)}</small></span>${icon('arrow')}</button>`).join('')}</div><p class="small">Choose the application dashboard after verification, rather than the identity provider or account portal.</p><p id="application-error" class="error" role="alert"></p>`,`<button id="application-back">Back</button>`);
 $('#application-back').onclick=()=>setupUI();
 document.querySelectorAll('[data-application]').forEach(b=>b.onclick=async()=>{
  b.disabled=true;const selected=pages[Number(b.dataset.application)];
  try{const connected=await api(`sessions/${setup.sessionId}/confirm`,{pageId:selected.pageId,url:selected.url});setup.url=connected.url;setup.signed=true;setup.paths=[];setup.discovered=false;setup.selected=new Set();setup.gaps=[];setupUI();toast('Signed-in application connected.');}
  catch(e){$('#application-error').textContent=e.message;b.disabled=false;}
 });
}
